// NewIPValidator initializes a new IPValidator object.
func NewIPValidator(opts ...IPValidatorOpt) *DefaultIPValidator {
	d := &DefaultIPValidator{
		netClient: &networkutils.DefaultNetClient{},
	}
	for _, opt := range opts {
		opt(d)
	}
	return d
}

